const a=(r,e="datetime")=>{if(!r)return"—";const t=new Date(r);if(isNaN(t.getTime()))return"Некорректная дата";const i={day:"2-digit",month:"2-digit",year:"numeric"};switch(e){case"date":return t.toLocaleString("ru-RU",i);case"time":return t.toLocaleString("ru-RU",{second:"2-digit",minute:"2-digit",hour:"2-digit"});case"datetime":return t.toLocaleString("ru-RU",{...i,minute:"2-digit",hour:"2-digit"});case"datetime-full":return t.toLocaleString("ru-RU",{...i,second:"2-digit",minute:"2-digit",hour:"2-digit"});default:return t.toLocaleString("ru-RU",{...i,minute:"2-digit",hour:"2-digit"})}},o=r=>{if(!r)return"";const e=new Date(r);if(isNaN(e.getTime()))return"";const t=e.getFullYear(),i=String(e.getMonth()+1).padStart(2,"0"),n=String(e.getDate()).padStart(2,"0");return`${t}-${i}-${n}`};export{o as d,a as f};
